using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based metadata for known types
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for Person: CreateObject != null → {personInfo.CreateObject is not null}");

// Round-trip using the typed metadata
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
var person = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-tripped: {person}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata unavailable
//    Use a resolver that only knows about 'int' to simulate a miss for 'Person'.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new IntOnlyResolver())
};

if (limited.TryGetTypeInfo(typeof(int), out var intInfo))
    Console.WriteLine($"int metadata available: {intInfo!.Type.Name}");
else
    Console.WriteLine("int metadata NOT available");

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Person metadata available (unexpected)");
else
    Console.WriteLine("Person metadata NOT available — no exception thrown ✓");

// --- Types & helpers ---

record Person(string Name, int Age);

/// A minimal resolver that only provides metadata for System.Int32.
sealed class IntOnlyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(int))
            return JsonMetadataServices.CreateValueInfo<int>(options, JsonMetadataServices.Int32Converter);
        return null;   // signals "I don't know this type"
    }
}

